    intro_playback_id: '',
    intro_parent_playback_id: '',
    intro_program_id: '',
    intro_request_id: '',
    intro_url: '',
    intro_started_at: 0,
    intro_rms: 0,
    intro_peak: 0,
    output_rms: 0.25,
    output_peak: 0.5,
    icecast_connected: true,
    sampled_at: 1_700_000_002.5,
