}

function lifecycle(sequence, event_type) {
  return {
    sequence,
    event_type,
    playback_request_id: 'request-1',
    playback_id: 'request-1',
    parent_playback_id: '',
    program_id: 'program-one',
    title: 'Test title',
    artist: 'Test artist',
