  telemetry.apply(snapshot(), [lifecycle(1, 'track_started')]);
  telemetry.expectTrackEnd('skipped');
  telemetry.apply(snapshot({ liquidsoap_sequence: 2, playing: false }), [
    lifecycle(1, 'track_started'),
