      lifecycle(2, 'track_ended'),
      {
        ...lifecycle(3, 'track_started'),
        playback_request_id: 'request-2',
        playback_id: 'request-2',
      },
    ],
  );

  const transitions = telemetry.replay.filter((event) =>
